import org.apache.commons.lang3.math.Fraction;

public class Probe {
    public static void main(String[] args) {
        p("getFraction(0.0)", Fraction.getFraction(0.0));
        p("getFraction(1.5)", Fraction.getFraction(1.5));
        p("getFraction(0.1)", Fraction.getFraction(0.1));
        p("getFraction(-2.75)", Fraction.getFraction(-2.75));
        p("getFraction(5.0)", Fraction.getFraction(5.0));
        p("getReducedFraction(2, MIN_VALUE)", Fraction.getReducedFraction(2, Integer.MIN_VALUE));
        try {
            Fraction f = Fraction.getFraction(1, 2);
            Fraction r = f.pow(Integer.MIN_VALUE);
            p("ONE_HALF.pow(MIN_VALUE)", r);
        } catch (Throwable t) {
            System.out.println("ONE_HALF.pow(MIN_VALUE) threw " + t);
        }
        try {
            Fraction r = Fraction.ONE.pow(Integer.MIN_VALUE);
            p("ONE.pow(MIN_VALUE)", r);
        } catch (Throwable t) {
            System.out.println("ONE.pow(MIN_VALUE) threw " + t);
        }
        p("getFraction(\"1.5\")", Fraction.getFraction("1.5"));
        p("getFraction(\"7/3\")", Fraction.getFraction("7/3"));
        p("getFraction(\"1 3/4\")", Fraction.getFraction("1 3/4"));
        p("getFraction(\"5\")", Fraction.getFraction("5"));
        try {
            Fraction.getFraction("1 2");
        } catch (Throwable t) {
            System.out.println("getFraction(\"1 2\") threw " + t);
        }
        try {
            Fraction.getFraction(Integer.MIN_VALUE, -1);
        } catch (Throwable t) {
            System.out.println("getFraction(MIN_VALUE,-1) threw " + t);
        }
        try {
            Fraction.getFraction(1, Integer.MIN_VALUE);
        } catch (Throwable t) {
            System.out.println("getFraction(1,MIN_VALUE) threw " + t);
        }
        try {
            Fraction a = Fraction.getFraction(Integer.MAX_VALUE, 1);
            Fraction b = Fraction.getFraction(1, 1);
            Fraction r = a.add(b);
            p("MAXV/1 add 1/1", r);
        } catch (Throwable t) {
            System.out.println("MAXV/1 add 1/1 threw " + t);
        }
        try {
            Fraction a = Fraction.getFraction(Integer.MAX_VALUE, 1);
            Fraction b = Fraction.getFraction(2, 1);
            Fraction r = a.multiplyBy(b);
            p("MAXV/1 * 2/1", r);
        } catch (Throwable t) {
            System.out.println("MAXV/1 * 2/1 threw " + t);
        }
        p("1/6 add 1/4", Fraction.getFraction(1,6).add(Fraction.getFraction(1,4)));
        p("getFraction(0,5).reduce()", Fraction.getFraction(0,5).reduce());
        p("getFraction(7,4).toProperString()", null); System.out.println(Fraction.getFraction(7,4).toProperString());
        System.out.println(Fraction.getFraction(-7,4).toProperString());
        System.out.println(Fraction.getFraction(5,5).toProperString());
        System.out.println(Fraction.getFraction(-5,5).toProperString());
        System.out.println(Fraction.getFraction(-7,4).intValue());
        System.out.println(Fraction.getFraction(-7,4).longValue());
    }
    static void p(String label, Fraction f) {
        if (f == null) return;
        System.out.println(label + " -> numerator=" + f.getNumerator() + " denominator=" + f.getDenominator());
    }
}
